import{_ as a,o as s,c as i,a2 as n}from"./chunks/framework.DCVnL8g5.js";const h=JSON.parse('{"title":"Introducción y casos de uso","description":"","frontmatter":{},"headers":[],"relativePath":"ia/vllm/01-introduccion-y-casos-de-uso.md","filePath":"ia/vllm/01-introduccion-y-casos-de-uso.md","lastUpdated":1789040978000,"isDraft":false}'),o={name:"ia/vllm/01-introduccion-y-casos-de-uso.md"};function l(t,e,r,c,p,d){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="introduccion-y-casos-de-uso" tabindex="-1">Introducción y casos de uso <a class="header-anchor" href="#introduccion-y-casos-de-uso" aria-label="Permalink to &quot;Introducción y casos de uso&quot;">​</a></h1><p>vLLM es un <strong>motor de inferencia</strong> para modelos de lenguaje: prioriza throughput y uso de VRAM cuando hay muchas peticiones a la vez. No entrena el modelo. No es un chatbot con UI. Cargas pesos (casi siempre desde Hugging Face) y o bien:</p><ul><li><strong>Offline:</strong> clase <code>LLM</code> en un script o job.</li><li><strong>Online:</strong> <code>vllm serve</code>, API HTTP compatible con OpenAI (capítulos 2 y 5).</li></ul><p>Documentación oficial: <a href="https://docs.vllm.ai/en/latest/examples/basic/offline_inference/" target="_blank" rel="noreferrer">offline inference</a>, <a href="https://docs.vllm.ai/en/latest/cli/serve/" target="_blank" rel="noreferrer">vllm serve</a>.</p><h2 id="que-problema-resuelve" tabindex="-1">Qué problema resuelve <a class="header-anchor" href="#que-problema-resuelve" aria-label="Permalink to &quot;Qué problema resuelve&quot;">​</a></h2><p>Generar tokens con <code>transformers.generate</code> en un bucle funciona para un notebook. En un servicio aparecen dos cuellos:</p><ul><li>La <strong>KV cache</strong> (claves/valores de atención) crece con el contexto y se fragmenta si la reservas en bloque contiguo.</li><li>Un <strong>batch estático</strong> espera a la secuencia más lenta: la GPU se queda a medio gas.</li></ul><p>vLLM usa <strong>PagedAttention</strong> (KV en bloques, como páginas de un SO) y <strong>continuous batching</strong> (el batch se recompone en cada paso de decode). El detalle operativo está en <a href="./04-batching-y-rendimiento">Batching y rendimiento</a>.</p><h2 id="cuando-usarlo" tabindex="-1">Cuándo usarlo <a class="header-anchor" href="#cuando-usarlo" aria-label="Permalink to &quot;Cuándo usarlo&quot;">​</a></h2><ul><li>API de chat/completions para una app (sustituir <code>api.openai.com</code> por tu GPU).</li><li>Jobs por lotes: muchas prompts, un proceso, una GPU.</li><li>Modelos que caben (o se parten con tensor parallelism) en las GPUs que tienes.</li></ul><p>Cuándo <strong>no</strong> es el primer paso:</p><ul><li>Probar un modelo de 0.5B en el portátil sin GPU: <code>transformers</code> o Ollama son más simples.</li><li>Fine-tuning: eso es Hugging Face / otros trainers.</li><li>Un único usuario ocasional que quiere una CLI local: Ollama suele ser mejor DX.</li></ul><h2 id="offline-minimo" tabindex="-1">Offline mínimo <a class="header-anchor" href="#offline-minimo" aria-label="Permalink to &quot;Offline mínimo&quot;">​</a></h2><p>Con vLLM instalado y una GPU NVIDIA visible:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> vllm </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> LLM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, SamplingParams</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">llm </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LLM(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">model</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Qwen/Qwen3-0.6B&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">params </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SamplingParams(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">temperature</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">max_tokens</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">outs </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> llm.generate([</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Explica PagedAttention en una frase.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], params)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(outs[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].outputs[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].text)</span></span></code></pre></div><p><code>LLM(...)</code> carga el modelo en VRAM. <code>generate</code> hace prefill + decode. El id del modelo es el del Hub (o una ruta local); el capítulo 3 cubre carga, <code>revision</code> y cuantización.</p><p>Para un servicio HTTP no uses este script en un <code>while True</code>: usa <code>vllm serve</code> (<a href="./05-despliegue">despliegue</a>).</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Tratar vLLM como “otro Hugging Face pipeline”. El runtime es distinto; los ejemplos de <code>pipeline</code> no se pegan aquí.</li><li>Pedir un modelo que no cabe y no mirar VRAM / <code>--max-model-len</code>.</li><li>Exponer el servidor a Internet sin clave ni red privada (capítulo 5).</li><li>Comparar latencia de una petición suelta con Transformers y concluir que “vLLM es igual de lento”: brilla con <strong>concurrencia</strong>.</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h2><ul><li>Empieza con un modelo pequeño que quepa de sobra; luego sube tamaño o <code>-tp</code>.</li><li>Fija el id del modelo en config, no en un comentario.</li><li>Mide tokens/s y TTFT con la carga real (capítulo 4 y 6), no con un único prompt de 5 tokens.</li><li>Separa “probar el motor” (<code>LLM</code>) de “publicar API” (<code>vllm serve</code>).</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Ejecuta el snippet offline con un modelo que quepa en tu GPU.</li><li>Lanza dos prompts en la misma llamada a <code>generate</code> y observa que salen las dos.</li><li>Anota en qué casos usarías Ollama, <code>transformers</code> o vLLM en tu proyecto.</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continúa con <a href="./02-servidor-openai-compatible">Servidor OpenAI compatible</a>.</p>`,25)])])}const k=a(o,[["render",l]]);export{h as __pageData,k as default};
